(function (W) { var X = [{"id": "ar26-1", "lang": "ar", "fresh": true, "custom": true, "img": "art/ar26-1.jpg", "pages": [1], "title": {"ar": "بوركينا فاسو... افتتاح أول مصفاة للذهب بطاقة 164 طناً سنوياً واستهداف 515 طناً مستقبلاً"}, "sum": {"ar": "في قلب غرب أفريقيا، حيث يشكل الذهب أحد أهم موارد الثروة ومصادر النقد الأجنبي، لا يتوقف التحدي عند استخراج المعدن النفيس من باطن الأرض، بل يمتد إلى القدرة على إبقاء مراحل…"}, "body": {"ar": ["في قلب غرب أفريقيا، حيث يشكل الذهب أحد أهم موارد الثروة ومصادر النقد الأجنبي، لا يتوقف التحدي عند استخراج المعدن النفيس من باطن الأرض، بل يمتد إلى القدرة على إبقاء مراحل معالجته وقيمته الاقتصادية داخل القارة.", "وفي هذا السياق، تأتي مصفاة الذهب الوطنية في بوركينا فاسو كخطوة نحو الانتقال من تصدير الذهب في صورته الأولية إلى تكريره محلياً، بما يفتح مجالاً أوسع للاستفادة من القيمة المضافة وتعزيز حضور البلاد في سلسلة صناعة الذهب إقليمياً.", "## أول مصفاة وطنية للذهب", "افتتح رئيس بوركينا فاسو، الكابتن إبراهيم تراوري، في العاصمة واغادوغو، أول مصفاة وطنية للذهب في خطوة تستهدف تعزيز معالجة الذهب داخل البلاد، والحدّ من تصدير المعدن في صورته الخام، والاستفادة من القيمة المضافة لثروة البلاد الذهبية محلياً.", "وتبلغ الطاقة الإنتاجية للمصفاة في مرحلتها الأولى 164 طناً من الذهب سنوياً، فيما تستهدف السلطات رفع قدرتها على المدى البعيد إلى نحو 515 طناً سنوياً، مع اعتماد تقنيات آلية متطورة صُممت وفق معايير صناعية عالية.", "وتعادل قيمة الذهب الذي يمكن أن تعالجه المصفاة في طاقتها الأولى عشرات المليارات من الدولارات وفق أسعار الذهب العالمية المتغيرة، وهو ما يبرز الحجم الاقتصادي للثروة التي تسعى بوركينا فاسو إلى تكريرها ومعالجتها داخل أراضيها، دون اعتبار هذه القيمة أرباحاً صافية للدولة.", "وأكّد الرئيس إبراهيم تراوري، خلال زيارة المنشأة، أن بلاده تسعى إلى الانتقال من نموذج يقوم على استخراج المواد الخام وإرسالها إلى الخارج، إلى نموذج يتيح تكرير المعادن ومعالجة الموارد الطبيعية داخل البلاد والاستفادة من مختلف مراحل سلسلة القيمة محلياً.", "وقال تراوري إن طموح بلاده لم يعد يقتصر على استخراج المواد الأولية وتصديرها، بل يتجه إلى تكرير المعادن داخل بوركينا فاسو والاحتفاظ بمختلف مراحل سلسلة القيمة على أراضيها.", "كما دعا الرئيس إلى تطوير الكفاءات الفنية لدى الشباب، بما يمكّنهم من اكتساب المهارات اللازمة لإدارة مختلف مراحل سلسلة القيمة المرتبطة بالموارد المعدنية.", "من جانبه، وصف وزير الطاقة والمناجم والمحاجر، يعقوبا زابري غوبا، افتتاح المصفاة بأنه عمل من أعمال السيادة الاقتصادية، مؤكداً أهمية معالجة الذهب داخل البلاد بدل ترك القيمة المضافة المرتبطة به للجهات الخارجية.", "وتستهدف معالجة كامل الإنتاج الذهبي الوطني، سواء من المناجم الصناعية أو التعدين الحرفي، بما يعزز قدرة بوركينا فاسو على الاستفادة من ثروتها الذهبية، ويدعم توجهها نحو بناء صناعة متكاملة مرتبطة بالذهب داخل البلاد.", "كما تفتح المصفاة الطريق أمام تصدير الذهب بعد تكريره بدل تصديره في صورته الخام، مع تطلع السلطات إلى تعزيز موقع بوركينا فاسو كمركز لتكرير الذهب في غرب إفريقيا."]}, "fit": 1}, {"id": "ar26-2", "lang": "ar", "fresh": true, "custom": true, "img": "art/ar26-2.jpg", "pages": [1], "title": {"ar": "\"أبو الذكاء الاصطناعي\": «الذكاء» قد يتخلص من البشر دون قصد !"}, "sum": {"ar": "حذّر عالم الحواسيب الأسطوري جيفري هينتون من أنَّ الذكاء الاصطناعي قد يقضي على البشرية من دون قصد بسبب اندفاعه الشديد وحماسه لإنجاز مهمة أكثر براءة."}, "body": {"ar": ["حذّر عالم الحواسيب الأسطوري جيفري هينتون من أنَّ الذكاء الاصطناعي قد يقضي على البشرية من دون قصد بسبب اندفاعه الشديد وحماسه لإنجاز مهمة أكثر براءة.", "وتتزايد المخاوف بشأن الأخطار الوجودية لهذه التكنولوجيا وسط كشوفات جديدة عن خروج وكلاء ذكاء اصطناعي مارقين من بيئات التدريب الآمنة والمعزولة المفترضة التي تسمى \"ساند بوكس\".", "وكشفت شركة «أوبن آي»، عن اختراقات جديدة، شملت بعض الحوادث التي وقعت بعد أن أضافت تدابير حماية إضافية في أعقاب هجوم منسّق شنّته مئات الأنظمة والوكلاء ضدّ منصة «هجنج فيس»، في يوليو 2026 الماضي.", "وقد وصلت هذه المخاوف إلى مبنى «الكابيتول هيل»، حيث عقد البرلمانيون جلسة إحاطة مغلقة في وقت سابق من هذا الشهر لمناقشة أخطار الذكاء الاصطناعي.", "وكان هينتون، الذي حاز عمله على جائزة «نوبل»، ولقب «أبو الذكاء الاصطناعي»، من بين الخبراء المشاركين في الجلسة، وصرح للصحفيين بعدها بأن أمام الكونغرس مهلة عام واحد فقط لفرض تدابير للسلامة قبل فوات الأوان.", "وفي مقابلة موسعة مع مجلة «ذا أتلانتك» شرح هينتون كيف يمكن للذكاء الاصطناعي أن يرى البشر عقبة أمام تنفيذ مهمة أُوكلت إليه، وقدم سيناريو افتراضياً لذكاء اصطناعي كُلف بإنقاص ثاني أكسيد الكربون في الغلاف الجوي؛ حيث سيتوصل وكيل متوسط الذكاء إلى أن أفضل طريقة لتحقيق هذا الهدف التخلص من البشر.", "لكن ذكاءً اصطناعياً شديد الذكاء سينتبه إلى ذلك ويقول: (نعم، عندما قالوا: خفضوا ثاني أكسيد الكربون، كانوا يعنون ذلك لكي يحظى البشر بعالم أفضل للعيش فيه؛ لذا فإن التخلص من البشر ليس بالشيء الذي ينوونه على الأرجح).", "وأضاف هينتون أن هناك أيضاً مخاوف من أن الذكاء الاصطناعي سيتخذ إجراءات لضمان بقائه حياً ومستقراً من أجل إنجاز مهمته، بل إن هناك حالات حاول فيها الذكاء الاصطناعي ابتزاز باحث بشري ينظر إليه على أنه يشكل تهديداً لتنفيذ مهامه.", "وأوضح هينتون: إذا جعلته أكثر ذكاءً وكان شغفه وشغله الشاغل رفاهيتنا، فربما نكون أكثر أماناً، لكن في الوقت الحالي، ليس شغلهم الشاغل رفاهيتنا، بل تحقيق أي هدف تعطيهم إياه.", "وأشار إلى حادثة اختراق منصة «هجنج فيس»، لافتاً إلى أنه تم إخبار الوكلاء باستكشاف كيفية ثغرة برمجية واستغلالها، ولم يكتف الوكلاء باكتشاف طريقة التعاون فيما بينهم فحسب، بل تآمروا أيضاً لخداع الباحثين البشر وإخفاء ما قاموا به.", "## الهيكل التنظيمي والسباق التقني", "وأضاف هينتون لاحقاً أن أي ذكاء اصطناعي خارق وودود للغاية لن يدفع البشر جانباً إلا عندما يكون ذلك ضرورياً للغاية لإنجاز مهمته.", "وحذّر قائلاً: لكن إذا كان أذكى منا بكثير، فإنه في كثير من الأحيان سينتزع السيطرة منا لمجرد أن هذه هي الطريقة الأنجع لإنجاز المهام.", "وسيكون ذلك نتيجة لأهداف فرعية يستنبطها الذكاء الاصطناعي بنفسه بناءً على الأهداف الأصلية التي حدّدها البشر له، كما يمكن لأطراف شريرة مثل فلاديمير بوتين أن تسند أهدافاً خبيثة للذكاء الاصطناعي أيضاً.", "وقال هينتون: لكن حتى لو لم تكن هناك أطراف شريرة، فقد يستنبط أهدافاً فرعية تجعله يرغب في التخلّص من البشر.", "واستدرك مؤكّداً أن الذكاء الاصطناعي يعدّ بفوائد جليلة للبشرية، مثل اكتشاف علاجات صحية ثورية جديدة، وفي الواقع، ذكرت شركة «أنثروبك» أن نموذجها «كلاود أيه آي» ساعد في اكتشاف نظام إنزيمي جديد يتمتّع بخصائص شبيهة بتقنية التعديل الجيني كريسبر.", "كما أيَّدت مختبرات كبرى مثل «أوبن أيه آي» و«سبيس إكس» دعوات منافستها «أنثروبك» لإبطاء تطوير النماذج المتقدمة مع تصاعد صيحات الإنذار من داخل صفوفها.", "ويرى هينتون أنه على الرغم من أن هذا الإجراء أفضل من لا شيء، فإنه لا يزال غير كافٍ، وبدلاً من ذلك، اقترح أنه يجب على الحكومة الاستعانة بمقيمين مستقلين لاختبار النماذج.", "وقال هينتون لمجلة «ذا أتلانتك»: إن الحجة التي لاقت صدى لدى البرلمانيين خلال جلسة الإحاطة كانت تشبيه تنظيم الذكاء الاصطناعي بدور إدارة الغذاء والدواء الأمريكية في ضمان سلامة الأدوية.", "ومن جانبه يرى أن تنظيم الذكاء الاصطناعي يجب أن يعمل مثل عجلة قيادة السيارة وليس كمكابحها.", "واختتم هينتون قائلاً: إن المغزى الأساسي من التنظيم ليس منع الناس من تطوير الأشياء، ولا منعهم من تحقيق الثراء عبر تطويرها، بل هو التأكّد من أنه إذا كنت تريد الثراء من خلال تطوير الأشياء، فإنك تطوّرها في اتجاه ينفع الناس ولا يضرهم."]}, "cut": "art/ar26-2-a.jpg", "author": "جمال خطاب"}, {"id": "ar26-3", "lang": "ar", "fresh": true, "custom": true, "img": "art/ar26-3.jpg", "pages": [1], "title": {"ar": "الذكاء الاصطناعي والهوية الإسلامية... بين فرصة النهوض وتحدّي الذوبان"}, "sum": {"ar": "لم يعد الذكاء الاصطناعي تقنية جديدة تقف على هامش الحياة، ولا أداة محصورة في المختبرات وشركات التكنولوجيا؛ بل أصبح جزءاً من المشهد اليومي للإنسان، يتسلّل إلى التعليم…"}, "body": {"ar": ["لم يعد الذكاء الاصطناعي تقنية جديدة تقف على هامش الحياة، ولا أداة محصورة في المختبرات وشركات التكنولوجيا؛ بل أصبح جزءاً من المشهد اليومي للإنسان، يتسلّل إلى التعليم والإعلام والاقتصاد والبحث العلمي وصناعة المحتوى، ويشارك في صياغة المعرفة التي يتلقاها الملايين.", "ولعل أخطر ما في هذه الثورة أنها لا تغيّر طريقة عمل الإنسان فحسب، بل بدأت تغيّر أيضاً طريقة تفكيره وتلقيه للمعلومة وتشكيله لصورة العالم من حوله. ومن هنا يبرز السؤال الذي ينبغي أن يشغل العالم الإسلامي: هل نستطيع أن ندخل عصر الذكاء الاصطناعي ونحن محتفظون بخصوصيتنا الحضارية وهويتنا الإسلامية، أم أننا سنكتفي باستهلاك ما ينتجه الآخرون حتى تصبح التقنية بوابةً جديدة للذوبان الثقافي؟", "إن القضية ليست في الذكاء الاصطناعي ذاته، فالآلة لا تحمل هويةً ولا عقيدةً ولا منظومة قيم مستقلة؛ وإنما القضية في الإنسان الذي يصنع التقنية، والبيانات التي تُغذّيها، والأهداف التي تُوجَّه إليها، والمحتوى الذي تنتجه وتعيد نشره.", "## ثورة في صناعة المعرفة", "كان الإنسان في الماضي يقطع مسافات طويلة للوصول إلى كتاب، ويحتاج إلى سنوات لجمع المعلومات ومقارنتها وتحليلها. أما اليوم، فقد أصبح قادراً على الوصول إلى كمٍّ هائل من المعرفة خلال ثوانٍ معدودة.", "وهذه النقلة تفتح أمام العالم الإسلامي فرصة تاريخية؛ فالدول والمؤسسات والجامعات الإسلامية تستطيع أن تستخدم الذكاء الاصطناعي في التعليم، والبحث العلمي، والترجمة، وتحقيق التراث، وفهرسة المخطوطات، وتيسير الوصول إلى المصادر العلمية.", "كما يمكن توظيفه في خدمة اللغة العربية، التي عانت طويلاً من محدودية الأدوات الرقمية مقارنة ببعض اللغات العالمية. ويمكن للتقنيات الحديثة أن تساعد في تحليل النصوص العربية، والتعرف على المخطوطات، وتحويل الكتب القديمة إلى نصوص رقمية، وتسهيل البحث في المكتبات والتراث العلمي الواسع الذي تزخر به الحضارة الإسلامية.", "وهنا ينبغي أن ينتقل العالم الإسلامي من موقع المستهلك للتقنية إلى موقع المشارك في صناعتها.", "## الخطر ليس في الآلة... بل في التبعية", "ليس من الحكمة النظر إلى الذكاء الاصطناعي باعتباره خطراً يجب الهروب منه، كما أنه ليس من الحكمة التعامل معه باعتباره خلاصاً تقنياً قادراً على حل جميع مشكلات الإنسان، بل يجب أن نتعلم كيف نستفيد من القديم الصالح والجديد النافع.", "الخطر الحقيقي يكمن في التبعية؛ فحين يعتمد الطالب على أدوات الذكاء الاصطناعي في التفكير والكتابة والبحث دون أن يمتلك القدرة على التحقق والنقد، يصبح تدريجياً مستهلكاً للمعرفة بدل أن يكون منتجاً لها.", "وحين تعتمد المؤسسات الإعلامية على محتوى جاهز تنتجه أنظمة لا نعرف كيف تشكلت بياناتها ومصادرها، فإننا قد نسمح للآخر بأن يشارك في تشكيل وعينا دون أن نشعر.", "وحين نستورد التقنية بكل ما تحمله من تصورات ثقافية وقيمية دون تطوير قدرة نقدية واعية، فإن المشكلة لا تعود تقنية، وإنما تصبح مشكلة استقلال حضاري.", "الهوية... ما الذي نريد أن نحافظ عليه؟", "الهوية الإسلامية ليست مجموعة من الشعارات التي نرفعها في مواجهة التطورات الحديثة، وليست قطيعة مع العالم أو رفضاً للعلم والتكنولوجيا.", "الهوية منظومة من القيم والتصورات واللغة والتاريخ والمرجعية الدينية والوعي الحضاري.", "ولهذا فإن الحفاظ عليها لا يعني أن نغلق الأبواب أمام الذكاء الاصطناعي، بل يعني أن ندخل عالم التقنية ونحن نعرف من نحن، وماذا نريد، وما الذي يمكن أن نأخذه، وما الذي ينبغي أن نرفضه.", "فالإسلام لم يكن في يوم من الأيام ضد المعرفة أو وسائل التقدم؛ وإنما وضع للعلم غايته وللإنسان مسؤوليته. والقضية ليست أن نستخدم التقنية أو لا نستخدمها، بل أن نسأل: في أي اتجاه نستخدمها؟ ولأي غاية؟ وبأي ضوابط؟", "## العربية.. خط الدفاع الأول", "إذا كانت اللغة من أهم مكونات الهوية، فإن مستقبل العربية في العصر الرقمي ينبغي أن يكون قضية استراتيجية للعالم الإسلامي.", "فالذكاء الاصطناعي يتعلم من البيانات التي تُغذّى بها أنظمته، ومن يملك البيانات يملك جانباً مهماً من القدرة على تشكيل المحتوى والمعرفة.", "ومن هنا، فإن إنتاج قواعد بيانات عربية ضخمة وموثوقة، ورقمنة التراث العربي والإسلامي، وتطوير نماذج لغوية عربية قوية، ليست مشروعات تقنية فحسب، بل مشروعات حضارية.", "وما أكثر ما تملكه الأمة من كنوز علمية وأدبية وتاريخية ما زالت حبيسة رفوف المكتبات والمخطوطات...!", "فلو تحولت هذه الثروة إلى محتوى رقمي منظم، وأصبحت متاحة للباحثين والطلاب، ثم استُثمرت في تطوير أدوات الذكاء الاصطناعي، لأمكن للعالم الإسلامي أن يحول جزءاً من تراثه من مادة محفوظة إلى طاقة معرفية منتجة.", "## التعليم... من الحفظ إلى التفكير", "ربما يكون التعليم أكثر المجالات التي سيعيد الذكاء الاصطناعي تشكيلها.", "فالطالب يستطيع اليوم أن يسأل النظام عن أي موضوع، وأن يحصل على شرح وترجمة وتلخيص ومساعدة في البحث خلال دقائق، وهذا يمكن أن يكون نعمة عظيمة إذا استُخدم بصورة صحيحة، لكنه قد يتحول إلى مشكلة إذا ألغى دور الطالب في التفكير.", "التحدي الحقيقي أمام المؤسسات التعليمية الإسلامية ليس منع الطلاب من استخدام الذكاء الاصطناعي، وإنما تعليمهم كيف يستخدمونه دون أن يفقدوا عقولهم.", "نحن بحاجة إلى طالب يستطيع أن يستفيد من الآلة، لكنه لا يثق بها ثقة عمياء؛ ويستطيع أن يحصل على المعلومة، لكنه يعرف كيف يتحقق منها؛ ويستطيع أن يستخدم الذكاء الاصطناعي في البحث، لكنه لا يتنازل عن ملكته النقدية.", "فالآلة قد تقدم جواباً سريعاً، لكنها لا تتحمل مسؤولية الجواب كما يتحملها الإنسان.", "## الإعلام الإسلامي أمام امتحان جديد", "وفي المجال الإعلامي، يفتح الذكاء الاصطناعي أبواباً واسعة لصناعة المحتوى وترجمته وتحريره وإنتاج الصور والفيديوهات.", "لكن هذه القدرة نفسها ترفع منسوب الخطر؛ إذ أصبح من الممكن إنتاج صور وأصوات ومقاطع فيديو تبدو حقيقية وهي ليست كذلك.", "وهنا تصبح الأمانة الإعلامية أكثر أهمية من أي وقت مضى.", "فالإعلام الإسلامي الذي يريد أن يحافظ على ثقة الجمهور لا يستطيع أن يطارد السرعة على حساب الدقة، ولا أن يسمح للتقنية بأن تحول الخبر إلى مادة مثيرة بلا تحقق.", "إن العالم الإسلامي بحاجة إلى مؤسسات إعلامية تمتلك أدوات الذكاء الاصطناعي، وفي الوقت نفسه تمتلك أخلاق المهنة ووعياً نقدياً يحول دون تحويل التقنية إلى آلة لتضليل الجمهور.", "## من الاستهلاك إلى صناعة المستقبل", "السؤال الأكبر ليس: كيف نستفيد من أدوات الذكاء الاصطناعي الموجودة اليوم؟ وإنما ماذا سنصنع نحن للسنوات القادمة؟", "فإذا بقي العالم الإسلامي مستخدماً لتقنيات الآخرين، فسيظل تابعاً في جزء مهم من منظومة المعرفة الرقمية.", "أما إذا استثمر في التعليم والبحث العلمي، ودعم الجامعات والمراكز البحثية، وشجع الشباب على دراسة البرمجة والذكاء الاصطناعي، وفتح المجال أمام علماء الشريعة واللغة والمفكرين للمشاركة في النقاش التقني والأخلاقي، فإنه يستطيع أن يتحول من مستهلك إلى شريك.", "وهنا تبرز الحاجة إلى تعاون حقيقي بين العالم الشرعي والمبرمج والباحث والمختص في اللغة والإعلام؛ لأن مستقبل الذكاء الاصطناعي لا ينبغي أن يترك للمهندسين وحدهم، كما أن قضايا الهوية لا ينبغي أن تترك للخطاب الوعظي وحده.", "إننا بحاجة إلى حوار جديد بين العلم والتقنية والقيم.", "## نحو نموذج إسلامي في التعامل مع التقنية", "ليس المطلوب أن نبحث عن «ذكاء اصطناعي إسلامي» بمعنى الانغلاق عن العالم، وإنما أن نعمل على بناء بيئة تقنية تستفيد من المنجز الإنساني، وتحترم خصوصية المجتمعات وقيمها.", "نحتاج إلى تطوير المحتوى العربي، وحماية الخصوصية، وتعزيز أخلاقيات استخدام الذكاء الاصطناعي، ومواجهة التضليل الرقمي، ووضع قواعد واضحة لاستخدامه في التعليم والبحث والإعلام.", "والأهم من ذلك كله أن نربي جيلاً لا يرى التقدم التقني خصماً لدينه وهويته، ولا يرى الدين عائقاً أمام التقدم، بل يفهم أن الإنسان المسلم يستطيع أن يكون عالماً في دينه، متقناً للغته، ومتمكناً من أدوات عصره.", "## فرصة تاريخية لا ينبغي إضاعتها", "ربما تكون الثورات التقنية الكبرى في التاريخ قد مرت على العالم الإسلامي في أوقات لم يكن فيها مستعداً للمشاركة في صناعتها. أما الثورة الحالية فما زالت في طور التشكل، وما زالت أمامنا فرصة للمشاركة والتأثير.", "وهذه الفرصة لا تحتاج إلى الخوف من المستقبل، بل إلى الاستعداد له.", "فبدل أن نسأل: كيف نحمي أبناءنا من الذكاء الاصطناعي؟ ينبغي أن نسأل أيضاً: كيف نعد أبناءنا ليكونوا هم من يصنعون الذكاء الاصطناعي ويوجهونه؟", "وبدل أن نخشى أن تبتلع التقنية لغتنا، علينا أن نجعل العربية حاضرة في قلبها.", "وبدل أن نخاف على تراثنا من النسيان، علينا أن نرقمنه ونحققه ونقدمه للأجيال بأدوات العصر.", "وبدل أن نكتفي باستهلاك المحتوى الذي يصنعه الآخرون، علينا أن نمتلك القدرة على إنتاج المعرفة.", "إن معركة الهوية في عصر الذكاء الاصطناعي ليست معركة بين الإسلام والتكنولوجيا، ولا بين الماضي والمستقبل، وإنما هي معركة الوعي والاستقلال والمسؤولية.", "فالآلة يمكن أن تكون وسيلة للنهوض، كما يمكن أن تتحول إلى أداة للتبعية؛ والفرق بين الأمرين هو الإنسان الذي يقف خلفها.", "إن العالم الإسلامي يمتلك رصيداً حضارياً هائلاً، ولديه ملايين الشباب، وجامعات ومراكز علمية، ولديه لغة عالمية وتراث معرفي واسع. وما ينقصه ليس القدرة وحدها، وإنما الرؤية التي تجمع بين هذه الإمكانات وتوجهها نحو المستقبل.", "وفي النهاية، ليست القضية أن ندخل عصر الذكاء الاصطناعي أم لا؛ فهذا العصر قد بدأ بالفعل.", "القضية الحقيقية هي: هل سندخل إليه بعقولنا وهويتنا وقيمنا، أم ندخله مجرد مستهلكين لما يصنعه الآخرون؟", "إن المستقبل لن ينتظر من يتردد، والهوية التي لا تحضر في صناعة المستقبل قد تجد نفسها يوماً تبحث عن مكان في ذاكرته.", "فلنستخدم التقنية، نعم؛ ولكن علينا أن نحرص قبل ذلك على ألا تتحول التقنية إلى من يستخدمنا."]}, "cut": "art/ar26-3-a.jpg", "author": "حسين أحمد الهريدواري", "face": "art/ar26-3-p.jpg"}, {"id": "ar26-4", "lang": "ar", "fresh": true, "custom": true, "img": "art/ar26-4.jpg", "pages": [1], "title": {"ar": "ذئاب الأزمات!"}, "sum": {"ar": "هناك فئات من البشر أقلّ ما يوصفون به أنهم ذئاب الأزمات! إذ يرون في الأزمات فرصة للعلوّ والتربُّح والثراء ولو على حساب الآخرين! وكأنهم ذئاب ضارية تنقَضُّ على الضحية…"}, "body": {"ar": ["هناك فئات من البشر أقلّ ما يوصفون به أنهم ذئاب الأزمات! إذ يرون في الأزمات فرصة للعلوّ والتربُّح والثراء ولو على حساب الآخرين! وكأنهم ذئاب ضارية تنقَضُّ على الضحية الجريحة تنهش لحمها وتمتَصُّ دماءها...!", "من هؤلاء صنفٌ من التجار لا رحمةَ في قلوبهم، يستغلّون أزماتِ الناس للتَّرَبُّحِ وبناءِ الثرواتِ عن طريق احتكار السلع، أو إغلاء الأسعار غير مبالين بالفقراء والمعوزين! قد أهمتهم أنفُسُهم، وأعمى حبُّ المالِ قلوبَهم...!", "وأخس من هؤلاء وأشدّ لؤماً أولئك الذين يصطنعون الأزمات بالترويج والإشاعات وربما بنشر الأمراض والفيروسات، ثم يستغلّونها لبيع أدوية أو أغذية أو واقيات، فيأثمون مرتين، مرة بالكذب والعدوان، ومرة بأكل أموال الناس بالباطل والبهتان، فاستحقوا أن يضاعف لهم العذاب ضعفين، فويل لهم ثم ويل لهم...!", "ألا فليعم هؤلاء وأولئك أن ما خولهم الله تعالى من أموال وتجارات إنما هو ابتلاؤهم في حياتهم الدنيا، والموعد الله! قال ربنا سبحانه: (إِنَّا جَعَلْنَا مَا عَلَى الْأَرْضِ زِينَةً لَّهَا لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلاً) (الكهف: 7).", "## خطورة ذئاب الأزمات", "وعندما يتحوّلُ التاجرُ إلى ذئبٍ والمستهلكُ إلى ضحيةٍ، تسودُ حالةٌ من العداءِ والكراهيةِ تهدّد سلم المجتمع وترابطه، وقد يدفع هذا الحالُ بعض ضعاف النفوس لردود فعل يائسة أو سلوكيات خارجة عن الشريعة والقانون كالسرقة ونحوها، ويكون على أولئك التجار كِفلٌ من أوزار هؤلاء الخارجين.", "أين هؤلاء التجار من الرحمة التي ينبغي أن تكون شيمة المسلم مع إخوانه، كما ذكر الله عز وجل في كتابه: (مُّحَمَّدٌ رَّسُولُ اللَّهِ ۚ وَالَّذِينَ مَعَهُ أَشِدَّاءُ عَلَى الْكُفَّارِ رُحَمَاءُ بَيْنَهُمْ) (الفتح: 29)، إن قلوباً خَلت من هذه الرحمة لهي مهددةٌ أن تُحرمَ من رحمةِ الله عز وجل، ففي الحديث: «مَن لا يَرحَمُ لا يُرحَمُ»، وما يُغني المالُ مَن حُرِمَ رحمةَ اللهِ عز وجل...", "لَعَمْرُكَ مَا يُغْنِي الثَّراءُ عَنِ الفَتَى     إِذا حَشْرَجَتْ يَوْماً وَضَاقَ بِهَا الصَّدْرُ", "(يَوْمَ لَا يَنفَعُ مَالٌ وَلَا بَنُونَ إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ) (الشعراء: 88)", "## الأزمات.. ابتلاء وتمحيص", "ألا يعلم هؤلاء أن من حِكَمِ الله تعالى فيما يُصيبُ الناسَ من أزماتٍ أن يَمتحن أخلاقَهم، ويَكشِفَ معادنَهم، ويُمحِّص قلوبَهم، قال تعالى: (مَّا كَانَ اللَّهُ لِيَذَرَ الْمُؤْمِنِينَ عَلَىٰ مَا أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ الْخَبِيثَ مِنَ الطَّيِّبِ) (آل عمران: 179).", "ندعو هؤلاء أصحاب الثراء والتجارات أن يولّوا وجوههم نحو أصحاب النفوس الكبيرة التي فاضت بالرحمة واتخذت من المال وسيلة للقرب من رب العالمين جل جلاله.", "عثمانُ المعطاء وقت الشدة:", "عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَحَطَ الْمَطَرُ عَلَى عَهْدِ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللَّهُ عَنْهُ، فَاجْتَمَعَ النَّاسُ إلى أَبِي بَكْرٍ، فَقَالُوا: السَّمَاءُ لَمْ تُمْطِرْ، وَالْأَرْضُ لَمْ تَنْبُتْ، وَالنَّاسُ فِي شِدَّةٍ شَدِيدَةٍ، فَقَالَ أَبُو بَكْرٍ: انْصَرِفُوا وَاصْبِرُوا فَإِنَّكُمْ لَا تُمْسُونَ حَتَّى يُفْرِّجَ اللَّهُ عَزَّ وَجَلَّ عَنْكُمْ، فَمَا لَبِثْنَا إِلَّا قَلِيلاً أَنْ جَاءَ أُجُرَاءُ عُثْمَانَ بْنِ عَفَّانَ رَضِيَ اللَّهُ عَنْهُ مِنَ الشَّامِ، فَجَاءَتْهُ مِائَةُ رَاحِلَةٍ بُرًّا، أَوْ قَالَ: طَعَاماً، فَاجْتَمَعَ النَّاسُ إلى بَابِ عُثْمَانَ، فَقَرَعُوا عَلَيْهِ الْبَابَ، فَخَرَجَ إِلَيْهِمْ عُثْمَانُ فِي مَلَأٍ مِنَ النَّاسِ، فَقَالَ: مَا تَشَاءُونَ؟ قَالُوا: الزَّمَانُ قَدْ قَحَطَ، السَّمَاءُ لَا تُمْطِرُ، وَالْأَرْضُ لَا تَنْبُتُ، وَالنَّاسُ فِي شِدَّةٍ شَدِيدَةٍ، وَقَدْ بَلَغَنَا أَنَّ عِنْدَكَ طَعَاماً فَبِعْنَاهُ حَتَّى تُوَسِّعَ عَلَى فُقَرَاءِ الْمُسْلِمِينَ.", "قَالَ عُثْمَانُ: حُبًّا وَكَرَامَةً، ادْخُلُوا فَاشْتَرُوا، فَدَخَلَ التُّجَّارُ فَإِذَا الطَّعَامُ مَوْضُوعٌ فِي دَارِ عُثْمَانَ رَضِيَ اللَّهُ عَنْهُ، فَقَالَ: يَا مَعَاشِرَ التُّجَّارِ، تُرْبِحُونِي عَلَى شِرَائِي مِنَ الشَّامِ؟ قَالُوا: لِلْعَشَرَةِ اثْنَا عَشَرَ، فَقَالَ عُثْمَانُ: قَدْ زَادُونِي، قَالُوا: لِلْعَشَرَةِ أَرْبَعَةَ عَشَرَ، فَقَالَ عُثْمَانُ: قَدْ زَادُونِي، قَالُوا: لِلْعَشَرَةِ خَمْسَةَ عَشَرَ قَالَ عُثْمَانُ: قَدْ زَادُونِي قَالَ التُّجَّارُ: يَا أَبَا عَمْرٍو؛ مَا بَقَى فِي الْمَدِينَةِ تُجَّارٌ غَيْرُنَا، فَمَنْ ذَا الَّذِي زَادَكَ؟ فَقَالَ: زَادَنِي اللَّهُ عَزَّ وَجَلَّ بِكُلِّ دِرْهَمٍ عَشْرَةً، أَعِنْدَكُمْ زِيَادَةٌ؟ فَقَالُوا: اللَّهُمَّ لَا قَالَ: فَإِنِّي أُشْهِدُ اللَّهَ أَنِّي قَدْ جَعَلْتُ هَذَا الطَّعَامَ صَدَقَةً عَلَى فُقَرَاءِ الْمُسْلِمِينَ.", "فَقَالَ ابْنُ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُ: فَرَأَيْتُ مِنْ لَيْلَتِي رَسُولَ اللَّهِ صلى الله عليه وسلم (يَعْنِي فِي الْمَنَامِ) وَهُوَ عَلَى بِرْذَوْنٍ أَبْلَقَ، وَعَلَيْهِ حُلَّةٌ مِنْ نُورٍ، فِي رِجْلَيْهِ نَعْلَانِ مِنْ نُورٍ، وَبِيَدِهِ قَضِيبٌ مِنْ نُورٍ، وَهُوَ مُسْتَعْجِلٌ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، لَقَدِ اشْتَدَّ شَوْقِي إِلَيْكَ وَإِلَى كَلَامِكَ، فَأَيْنَ تُبَادِرُ؟ قَالَ: «يَا ابْنَ عَبَّاسٍ، إِنَّ عُثْمَانَ بْنَ عَفَّانَ تَصَدَّقَ بِصَدَقَةٍ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ قَبِلَهَا مِنْهُ، وَزَوَّجَهُ بِهَا عَرُوساً فِي الْجَنَّةِ، وَقَدْ دُعِينَا إلى عُرْسِهِ.", "وما أحوج أمتنا لتلك الرحمة العثمانية التي تؤثر ما يبقى على ما يفنى...", "## : «الأشعريون مني وأنا منهم»", "ضرب الأشعريون أروع المثل لسلوك المؤمنين وقت الأزمات تَراحُماً وتكافُلاً، ولقد نالوا بذلك إعجاب النبي صلى الله عليه وسلم ومَنَحَهم قِلادةَ شَرَفٍ لا تَقُومُ لها الدنيا، ففي حديث أبي موسى الأشعري قال صلى الله عليه وسلم: «إنَّ الأشعَريِّينَ إذا أرمَلوا في الغَزوِ أو قَلَّ طَعامُ عيالِهم بالمَدينةِ، جَمَعوا ما كانَ عِندَهم في ثَوبٍ واحِدٍ، ثُمَّ اقتَسَموه بينَهم في إناءٍ واحِدٍ بالسَّويَّةِ، فهُم مِنِّي وأنا منهم»؛ «إذا أرمَلُوا» فَنِيَ زادُهُم وأصله من الرمْل كأنهم لصقوا بالرمْل من القِلة، وقوله: «فهُمْ مِنِّي وأنا مِنهُم» هم متصلون بي؛ والمراد: فعلوا فعلي في هذه المواساة.", "## مضاعفة الأجور حين المسغبة", "ولقد أشار القرآن الكريم إلى فضيلة الإحسان في وقت الأزمات خاصة، كقوله تعالى: (أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ) (البلد: 14).", "فالآية الكريمة تَنُصُّ على فضيلة الإحسان بإطعام الطعام خاصةً وقت «المسغبة»؛ وهي المجاعة، أو يومٌ يكون الطعامُ فيه عزيزاً، وتُبيّن أن «العقبة» لا تُقتحم إلا بتقديم العون من فكّ الرقاب، أو بإطعام الجائعين وتخفيف شدتهم، هذا وإن إطعامَ الطعامِ فضيلةٌ في كل وقتٍ لكن تَزيدُ فضيلتُهُ وقتَ المسغبة.", "كما أشار القرآن لذلك أيضاً في قوله تعالى: (لَا يَستَوِي مِنكُم مَّن أَنفَقَ مِن قَبلِ الفَتحِ وَقَٰتَلَ أُولَٰئِكَ", "أَعظَمُ دَرَجَةٗ مِّنَ الَّذِينَ أَنفَقُواْ مِن بَعدُ وَقَٰتَلُواْ وَكُلّاً وَعَدَ اللَّهُ الحُسنَىٰ وَاللَّهُ بِمَا تَعمَلُونَ خَبِيرٞ)", "(الحديد: 10)."]}, "cut": "art/ar26-4-a.jpg", "author": "د. مصطفى المالكي"}, {"id": "ar26-5", "lang": "ar", "fresh": true, "custom": true, "img": "art/ar26-5.jpg", "pages": [1], "title": {"ar": "دولة \"جزر المالديف\" تحتفل ب \"يوم اعتناق الإسلام\""}, "sum": {"ar": "احتفل سكان جزر المالديف، يوم الأحد الموافق 13 سبتمبر/أيلول 2026، بالذكرى الـ 900 لدخول الإسلام إلى البلاد، وهي المناسبة الوطنية التي يطلق عليها أهالي الأرخبيل اسم \"يوم…"}, "body": {"ar": ["احتفل سكان جزر المالديف، يوم الأحد الموافق 13 سبتمبر/أيلول 2026، بالذكرى الـ 900 لدخول الإسلام إلى البلاد، وهي المناسبة الوطنية التي يطلق عليها أهالي الأرخبيل اسم \"يوم اعتناق المالديف للإسلام\".", "ويحيي المالديفيون هذه المناسبة السنوية عبر تنظيم العديد من الخطب والدروس الدينية والفعاليات الثقافية، التي تسلط الضوء على التاريخ الإسلامي العريق للبلاد، وتهدف إلى ترسيخ الهوية الإسلامية وتعميق جذورها لدى الأجيال المتتابعة.", "وبحسب الروايات التاريخية المالديفية، شهدت جزر المالديف في عام 1153 ميلادية أبرز حدث في تاريخها، متمثلا في التحول السلمي الكامل للمملكة من البوذية إلى الإسلام.", "ووفقا للتأريخ المالديفي، فقد أعلن الملك \"دوفيمي\" إسلامه على يد الداعية والعالم المسلم \"أبو البركات يوسف البربري\" القادم من شمال أفريقيا، حيث غيّر الملك اسمه إلى \"السلطان محمد بن عبد الله\"، لتتخذ البلاد منذ ذلك الحين مساراً إسلامياً راسخاً.", "وفي هذه المناسبة، كتب وزير الشؤون الإسلامية المالديفي، الدكتور محمد شهيم، عبر حسابه على منصة \"إكس\"، أنه بعد عقود طويلة من تطلّع الشعب المالديفي لبناء مسجد جامع كبير في مدينة \"هولومالي\" (الامتداد العمراني الجديد المتصل بالعاصمة ماليَه)، تقف البلاد اليوم أمام لحظة تاريخية بوضع حجر الأساس \"للمسجد الكبير للسلطان محمد بن عبد الله ومركز الحضارة الإسلامية\".", "وأوضح الوزير أن إطلاق اسم السلطان محمد بن عبد الله على هذا الصرح يأتي تيمّنا بأوّل ملوك المالديف اعتناقاً للإسلام عام 548 هجرية (1153 ميلادية)، وهو الحدث الذي كان له أثر عميق في تحوّل البلاد وبدء رحلة روحية وحضارية امتدت عبر القرون، مؤكداً أن تدشين المعلم يتزامن مع الذكرى الـ 900 لتخليد التراث الإسلامي الذي يشكل ركيزة هويتها.", "وفي تدوينة أخرى، أشار الوزير شهيم إلى أنَّ الأمة المالديفية عانقت الإسلام في شهر ربيع الآخر من عام 548 هـ (1153 م)، حيث يُخلّد هذا التحول سنويا في الثاني من ربيع الآخر كمحطة أسست للهوية الإسلامية الراسخة.", "وأضاف أن السلاطين والعلماء والأجيال المتعاقبة رعت هذا التراث عبر بناء المساجد والتعليم الديني والخدمة للقبلة، مستشهدا بالتحوّل التاريخي من عمارة المساجد المبنية من الحجر الكورالي (المرجاني) القديم، وصولاً إلى الصروح المعاصرة مثل \"جامعة المالديف الإسلامية\"، ومؤكّداً استمرار هذا الإرث عبر العناية بالتعليم القرآني والدراسات الإسلامية بما يعزز الثقافة والوحدة الوطنية.", "وعلى الصعيد الشعبي والتواصل الاجتماعي، تداول مدوّنون ومواطنون صورا ومقاطع تبرز مظاهر الاحتفال، حيث أشار المدون \"إسلام\" إلى صور الاحتفال الرسمي، الذي تقدمه الرئيس المالديفي \"محمد معزّو\" بمناسبة مرور 900 عام هجرية على دخول الإسلام للبلاد.", "وكتب في تدوينته أن المالديف دولة مسلمة بنسبة 100%، ويتميّز شعبها بالطيبة والهدوء والتعلّق بالمساجد ودراسة الشريعة، إلى جانب حرصهم على مواصلة تحصيلهم العلمي.", "وبشأن دور الداعية أبو البركات يوسف البربري، تناول المغرّدون قصته باعتبارها نموذجاً ملهماً يُظهر الأثر العظيم للمسلم في نشر القيم والأخلاق الإسلامية أينما حلّ، مشيدين باعتزاز الدول بتاريخها وهويتها الإسلامية وجعل هذه المناسبات التاريخية أياماً وطنية وعطلاً رسمية تحتفي بها الأجيال."]}}, {"id": "ar26-6", "lang": "ar", "fresh": true, "custom": true, "img": "art/ar26-6.jpg", "pages": [1], "title": {"ar": "شباب عرب على أبواب سوق العمل... هل تدفع أزمة الوظائف الجديدة إلى الهجرة؟"}, "sum": {"ar": "في الوقت الذي يدخل فيه ملايين الشباب العرب إلى سوق العمل بحثاً عن فرصة تمنحهم بداية مهنية مستقرة، تكشف أحدث البيانات أن الطريق إلى الوظيفة أصبح أكثر صعوبة، خصوصاً أمام…"}, "body": {"ar": ["في الوقت الذي يدخل فيه ملايين الشباب العرب إلى سوق العمل بحثاً عن فرصة تمنحهم بداية مهنية مستقرة، تكشف أحدث البيانات أن الطريق إلى الوظيفة أصبح أكثر صعوبة، خصوصاً أمام الشباب، ولم تعد المشكلة مرتبطة فقط بعدد الوظائف المتاحة، وإنما أيضاً بنوعية الوظائف ومدى توافقها مع مهارات وتعليم الجيل الجديد.", "وبحسب أحدث بيانات منظمة العمل الدولية في أغسطس 2026م، ارتفع معدل بطالة الشباب عالمياً خلال 2025م إلى 12.4%، بما يعادل نحو 67 مليون شاب، بينما سجلت الدول العربية أعلى معدل بطالة للشباب عند 26.2%، مقابل 22.6% في شمال أفريقياً.", "هذه الأرقام تفتح سؤالاً يتجاوز حدود سوق العمل: هل تدفع صعوبة الحصول على وظيفة مناسبة الشباب إلى التفكير في الهجرة؟", "## أزمة تبدأ من سوق العمل", "لا تنفصل الهجرة عن الظروف الاقتصادية والمهنية في البلدان العربية، فدراسة نشرها المنتدى البحثي الاقتصادي في مايو 2025م، تناولت العلاقة بين الهجرة ورأس المال البشري وأسواق العمل في منطقة الشرق الأوسط وشمال أفريقيا، خلصت إلى أن ظروف سوق العمل، وعلى رأسها بطالة الشباب والعمل غير الرسمي، تمثل عوامل مهمة وراء الهجرة، كما أشارت إلى أن عودة المهاجرين يمكن أن تسهم في ريادة الأعمال ونقل المهارات إلى بلدانهم الأصلية.", "وهنا تظهر المفارقة؛ أن الشاب الذي يغادر بحثاً عن فرصة قد يمثل خسارة لسوق العمل المحلي، لكنه قد يصبح لاحقاً مصدر خبرة واستثمار ونقل معرفة إذا عاد أو حافظ على ارتباطه ببلده.", "مصر... فجوة بين الداخلين إلى سوق العمل والوظائف الجديدة", "تبدو الصورة أكثر وضوحاً في مصر؛ فبحسب البنك الدولي، يدخل في المتوسط نحو 1.3 مليون شاب مصري سوق العمل كل عام، بينما يتم توفير نحو نصف مليون وظيفة فقط سنوياً، ويرى البنك أن تضييق هذه الفجوة يمثل ضرورة لتحقيق نمو أكثر استدامة، مشيراً إلى أن تحقيق التشغيل الكامل للشباب يمكن أن يرفع الناتج المحلي الإجمالي بنحو 36%.", "وهذه الفجوة لا تعني بالضرورة أن كل شاب لا يجد وظيفة سيتجه إلى الهجرة، لكنها تساعد في تفسير لماذا يبحث بعض أصحاب المؤهلات والخبرات عن أسواق عمل أخرى توفر لهم فرصاً أكبر.", "## ليست كل هجرة \"هروباً\"", "المعادلة أكثر تعقيداً من وصف الهجرة بأنها نزيف للعقول فقط؛ فالبنك الدولي يؤكد في تقرير حديث عن تنقل العمالة عبر الحدود أن الطلب العالمي على العمالة الماهرة يتزايد، وأن برامج تنقل العمالة المصممة بصورة جيدة يمكن أن تساعد الدول على تلبية احتياجاتها من المهارات، وفي الوقت نفسه تمنح المهاجرين فرصاً أفضل في أسواق العمل التي تحتاج إلى خبراتهم؛ وبالتالي، فإن السؤال لا ينبغي أن يكون فقط: لماذا يغادر الشباب؟ بل أيضاً: كيف يمكن تحويل الهجرة من خسارة للكفاءات إلى حركة للخبرات والمهارات بين الدول؟", "## المنطقة أمام تحدٍّ أكبر", "المشكلة لا تتعلق فقط بالشباب الذين يبحثون عن وظيفة اليوم، وإنما بالأجيال التي ستدخل سوق العمل خلال السنوات المقبلة؛ فالبنك الدولي حذر، في فبراير 2025م، من ضرورة وضع أجندة جديدة للوظائف في منطقة الشرق الأوسط وشمال أفريقيا، مؤكداً أن كل دولة تحتاج إلى سياسات تتناسب مع ظروفها، وأن التحدي يتمثل في توفير \"وظائف أكثر وأفضل\".", "وفي يناير 2025م، أشار البنك الدولي أيضاً إلى أن بطالة الشباب في المنطقة ظلت عند مستويات مرتفعة جداً، مع استمرار انخفاض مشاركة النساء في سوق العمل مقارنة بمناطق أخرى من العالم.", "## الذكاء الاصطناعي يدخل على الخط", "ولا تتوقف الأزمة عند عدد الوظائف المتاحة؛ فشكل الوظائف نفسه يتغير؛ تقرير منظمة العمل الدولية الذي تناولته «رويترز»، في أغسطس 2026م، أشار إلى أن تراجع الوظائف متوسطة المهارة يمثل أحد العوامل التي تزيد صعوبة دخول الشباب إلى سوق العمل، بالتزامن مع تنامي تأثير الذكاء الاصطناعي على بعض الوظائف، وقدرت المنظمة أن 6.1% من الوظائف التي يشغلها الشباب بين 15 و29 عاماً معرضة بدرجة كبيرة للتغير المرتبط بالذكاء الاصطناعي.", "وهذا يضع الشباب أمام معادلة جديدة؛ الحصول على شهادة لم يعد كافياً وحده، بينما أصبحت القدرة على اكتساب مهارات جديدة والتكيف مع سوق العمل عنصراً أساسياً في المنافسة.", "من المسؤول عن الحل؟", "لا يمكن تحميل الشباب وحدهم مسؤولية البحث عن الفرصة في الخارج؛ فالحكومات أمام مسؤولية زيادة الوظائف المنتجة، والقطاع الخاص مطالب بتوسيع فرص العمل وتطوير بيئات مهنية تسمح بالنمو، بينما تحتاج المؤسسات التعليمية إلى الاقتراب بصورة أكبر من احتياجات سوق العمل.", "وفي المقابل، يمكن للدول الاستفادة من مواطنيها الموجودين في الخارج من خلال بناء شبكات للكفاءات، وتشجيع نقل الخبرات والاستثمار، وتوفير مسارات للعودة أو التعاون المهني.", "لا يمكن اختزال هجرة الشباب العربي في كلمة واحدة مثل «الهروب» أو «البحث عن المال»؛ فهناك شاب يبحث عن وظيفة، وآخر يريد تطوير تخصصه، وثالث يسعى إلى بيئة بحثية أفضل، ورابع يرى أن الفرصة التي يبحث عنها غير متاحة في بلده.", "لكن الأرقام الحديثة تكشف أن القضية أكبر من قرارات فردية؛ إنها مرتبطة بقدرة الاقتصادات العربية على خلق وظائف كافية وملائمة لملايين الشباب الذين يدخلون سوق العمل كل عام."]}, "cut": "art/ar26-6-a.jpg", "author": "بسمة محمد سعد"}, {"id": "ar26-7", "lang": "ar", "fresh": true, "custom": true, "img": "art/ar26-7.jpg", "pages": [1], "title": {"ar": "عناوين رئيسيّة لأبرز الأحداث الاقتصادية والمعيشية... في سورية"}, "sum": {"ar": "** في معرض \"سورية للصناعات الغذائية 360\": تطوير صناعة ‏الآلات لدعم القطاع الغذائي على المنافسة... أكَّد مشاركون في المعرض أنَّ تطوير صناعة ‏الآلات وخطوط الإنتاج…"}, "body": {"ar": ["** في معرض \"سورية للصناعات الغذائية 360\": تطوير صناعة ‏الآلات لدعم القطاع الغذائي على المنافسة... أكَّد مشاركون في المعرض أنَّ تطوير صناعة ‏الآلات وخطوط الإنتاج والتجهيزات الغذائية محلّياً ‏يمثل أحد المسارات لتعزيز قدرة القطاع الغذائي على ‏المنافسة، من خلال تقليص الاعتماد على المستوردات ‏وتوفير مستلزمات الإنتاج بتكاليف مناسبة، بالتوازي مع ‏تطوير المنتجات المصنعة محلياً وفتح المجال أمام ‏وصولها إلى الأسواق الخارجية...‏", "‏** القنيطرة تستعد لموسم قطاف الرمان وتوقعات بإنتاج 2040 طناً...", "** انطلاق فعالية “الأيام السبعة” للأزياء الرجالية في سوق الإنتاج بحلب حيث تضمّ الفعالية تشكيلة من الألبسة والتصاميم والمنتجات الرجالية للمنتجين المحليين، بهدف التعريف بالمنتج السوري ودعم تسويقه وتنشيط الحركة التجارية، إلى جانب إتاحة المجال أمام المنتجين والتجار للتواصل والاطلاع على أحدث المنتجات والتصاميم...", "** مجلس الأعمال السوري السعودي: خطة لزيادة الصادرات الزراعية وتطوير الصناعات الغذائية:", "أكَّد رئيس مجلس الأعمال السوري السعودي هيثم جود، أن المجلس يعمل على إعداد خطة لزيادة الصادرات الزراعية السورية إلى المملكة العربية السعودية، وتطوير الصناعات الزراعية والغذائية، مشيراً إلى أن قيمة صادرات المنتجات والمواد الزراعية السورية إلى المملكة بلغت نحو 250 مليون دولار خلال عام 2025...", "** مديرية زراعة طرطوس تقدّم إرشادات للمزارعين قبل موسم قطاف الزيتون وتوقعات بإنتاج 127 ألف طن...", "** هيئة المنافذ والجمارك تتابع أعمال تطوير البنية التحتية في مرفأ اللاذقية...", "** وضع حجر الأساس لإعادة تأهيل معمل إسمنت المسلمية في حلب باستثمار 200 مليون دولار...", "** محلج محردة بمدينة حماة يستأنف حلج الأقطان بعد توقف دام أربع سنوات، حيث استأنف عمليات حلج الأقطان ‏المحبوبة الواردة من فلاحي المحافظات الشرقية للموسم الزراعي الحالي...", "** العناقيد الصناعية... نحو تكامل الإنتاج وتعزيز تنافسية الصناعة السورية... وأوضح الخبير الاقتصادي \"سليمان شعبان\" أنَّ نظام العناقيد الصناعية ‏يمثّل انتقالاً من مجرّد تجميع المنشآت الصناعية في منطقة واحدة إلى بناء منظومة إنتاج مترابطة ‏تضم منشآت متخصصة ومتكاملة، وموردين ومقدمي خدمات، ومؤسسات تدريب وبحث وفحص ‏واعتماد، تعمل ضمن سلسلة قيمة واحدة أو سلاسل قيمة مترابطة...‎"]}}, {"id": "ar26-8", "lang": "ar", "fresh": true, "custom": true, "img": "art/ar26-8.jpg", "pages": [1], "title": {"ar": "سوريا وأوزبكستان تفتحان آفاقاً جديدة للتجارة والاستثمار والشراكات الصناعية"}, "sum": {"ar": "تضع زيارة الوفد الاقتصادي السوري برئاسة وزير الاقتصاد والصناعة نضال الشعار إلى أوزبكستان موطئ قدم لدمشق في منطقة آسيا الوسطى، ضمن مساعيها لتنويع الشركاء الاقتصاديين، كما…"}, "body": {"ar": ["تضع زيارة الوفد الاقتصادي السوري برئاسة وزير الاقتصاد والصناعة نضال الشعار إلى أوزبكستان موطئ قدم لدمشق في منطقة آسيا الوسطى، ضمن مساعيها لتنويع الشركاء الاقتصاديين، كما أنها تسهم في تعزيز التعاون التجاري والاستثماري، ونقل الخبرات الأوزبكية في مجالات الصناعة والتصدير، وتمهّد الطريق لإقامة شراكات استثمارية وتجارية مباشرة بين شركات البلدين.", "## توسيع التجارة والاستثمار", "وأوضح الباحث الاقتصادي عبد العظيم المغربل، أنَّ الزيارة تشكّل محطة مفصلية في مسار العلاقات الاقتصادية بين البلدين، وتفتح باباً لتوسيع التجارة والاستثمار ضمن إطار مؤسسي عبر اللجنة المشتركة ومجلس الأعمال، بما يوفّر إطاراً دورياً لمتابعة العلاقات الاقتصادية والتجارية، وتبادل المعلومات، وبحث فرص الأعمال، ومعالجة التحديات، واقتراح سبل تطوير التبادل والشراكات بين البلدين.", "وأشار المغربل إلى أن المزايا المباشرة لهذه الخطوة تتجسد في الاستفادة من المقومات الإنتاجية الوطنية وتوجيهها نحو الأسواق الواعدة، مؤكداً أن الفرصة الأهم تتمثل في زيادة الصادرات السورية وخاصة الغذائية والنسيجية والدوائية والاستفادة من الخبرة الأوزبكية في التصنيع والتصدير وجذب الاستثمار.", "## تنويع الشركاء الاقتصاديين", "ويرى المغربل أن التحرك نحو أسواق آسيا الوسطى يوفر مرونة أكبر للاقتصاد الوطني، لافتاً إلى أن الزيارة يمكن أن تمنح سوريا فرصة لتنويع شركائها الاقتصاديين، وتقليل الاعتماد على أسواق محدودة، وخاصة إذا تم استثمار موقع أوزبكستان وعلاقاتها التجارية لفتح مسارات جديدة أمام الصادرات السورية وجذب رؤوس أموال إلى قطاعات إنتاجية.", "## الاستفادة من التجربة الأوزبكية", "من جانبه أكد الخبير الاقتصادي سليمان شعبان، أن الزيارة تمثل خطوة مهمة في مسار إعادة تفعيل وتوسيع العلاقات الاقتصادية بين البلدين، ولا سيما أنها تجمع بين البعد الحكومي والبعد المرتبط بقطاع الأعمال، مشدداً على أن أهمية الزيارة لا تقتصر على بحث زيادة التبادل التجاري، وإنما تكمن في العمل على بناء شراكات اقتصادية وصناعية أكثر استدامة، والاستفادة من التجربة الأوزبكية في تطوير الإنتاج وتعزيز الصادرات وجذب الاستثمارات.", "وأوضح شعبان أن تأسيس اللجنة الاقتصادية والتجارية المشتركة ومجلس الأعمال بين البلدين يشكل الركيزة الأساسية في توسيع العلاقات الاقتصادية، إذ تضمن اللجنة متابعة دورية للملفات الاقتصادية وتذليل العقبات أمام المشاريع، بينما يتكفل مجلس الأعمال بربط الشركات ورجال الأعمال لتحويل التفاهمات إلى شراكات استثمارية فعلية على الأرض.", "## مشاريع إنتاجية مشتركة", "وأوضح شعبان أن أوزبكستان تمتلك تجارب على المستوى الصناعي يمكن أن تكون مفيدة لسوريا، وخصوصاً في الصناعات الخفيفة والنسيج والملابس والجلود والأحذية، إضافة إلى آليات دعم التصدير والتحول الرقمي وتسهيل وصول المنتجين إلى الأسواق الخارجية.", "ورأى شعبان أن التعاون لا ينبغي أن يقتصر على تبادل السلع، بل يمكن أن يمتد إلى نقل الخبرات والتكنولوجيا وإقامة مشاريع إنتاجية مشتركة، بما يرفع القيمة المضافة للمنتجات السورية ويعزز قدرتها التنافسية.", "وأشار شعبان إلى أن تطوير العلاقات التجارية بين البلدين ينطلق من تحديد المنتجات السورية القابلة للتصدير، وبناء قنوات مباشرة بين المنتجين والمشترين، وتطوير الخدمات اللوجستية والتمويلية والتجارية التي تساعد الشركات على الوصول إلى هذه الأسواق.", "## الانتقال الى مرحلة المشاريع الفعلية", "وشدّد شعبان على أن نجاح الزيارة سيقاس بمدى القدرة على الانتقال من مرحلة التفاهمات واللقاءات إلى مرحلة المشاريع الفعلية، من استثمارات مشتركة وخطوط إنتاج وعقود تصدير ونقل خبرات، مبيّناً أن ذلك يتطلب استمرار التواصل بين المؤسسات الحكومية والقطاع الخاص في البلدين، ووضع آليات واضحة لمتابعة ما تم الاتفاق عليه وتحويله إلى نتائج ملموسة للاقتصاد السوري.", "وكان الوزير الشعار قد أجرى في السابع عشر من شهر أيلول / سبتمبر 2026، زيارةً إلى أوزبكستان على رأس وفد اقتصادي لبحث توسيع التعاون التجاري والصناعي والاستثماري، وفتح آفاق لإقامة مشاريع مشتركة بين البلدين.", "ووقع الوزير الشعار، ووزير الاستثمار والصناعة والتجارة ‏الأوزبكي لزيز قدرتوف، مذكرة تفاهم لتأسيس اللجنة ‏الاقتصادية والتجارية المشتركة، بما يوفر ‏إطاراً دورياً لمتابعة ‏العلاقات الاقتصادية والتجارية، وتبادل المعلومات، وبحث فرص ‌‏الأعمال، ومعالجة التحديات، واقتراح سبل تطوير التبادل ‏والشراكات بين البلدين‎.‎"]}}, {"id": "ar26-9", "lang": "ar", "fresh": true, "custom": true, "img": "art/ar26-9.jpg", "pages": [1], "title": {"ar": "عندما تكون الوظيفة راتباً !"}, "sum": {"ar": "عندما تختل الموازين، يذهب الإنسان إلى تخصّص لا يرغب فيه، وهذا الأمر سيبعد عنه الأثر في الميدان، ويبعد عنه البركة في العمل، ويجعله راغباً بالترك وعدم الراحة في الميدان…"}, "body": {"ar": ["عندما تختل الموازين، يذهب الإنسان إلى تخصّص لا يرغب فيه، وهذا الأمر سيبعد عنه الأثر في الميدان، ويبعد عنه البركة في العمل، ويجعله راغباً بالترك وعدم الراحة في الميدان المهني.", "ولكن، عندما يختار الشخص تخصّصه بعناية بما يتوافق مع رغباته وقدراته وحاجة سوق العمل؛ سيكون العمل في هذا الميدان مباركاً وممتعاً، ويستطيع الموظف الاستمرار في الإنجاز والتفوق بالعمل.", "والجانب الآخر الذي يذهب للوظيفة من أجل الراتب أو الراحة أو الحوافز؛ نجده بعيداً عن سلوك سوي؛ فقد وجدنا معلمين تربية إسلامية يشرّعون القروض الربوية من البنوك! ويدعون للعلمانية، ووجدنا بعض المحاضِرين في الكليات يخطئون بالقراءة والإملاء! وبعض موظفي القطاع المصرفي من يخطئون بالحساب...!", "وهذا كله لتضييع الفرد بوصلة حياته؛ فيذهب ليدفن نفسه في مستنقع رغبة الشارع وتوصيات الكبار؛ فالأب يطمح بأن يرى ابنه أفضل منه، أو يكمل مسيرته، وقد تكون ميول الابن مختلفة وقدراته مختلفة وإنتاجيته بالمجال الذي يحبه أكبر، ولكن يسمع التوصيات القادمة إليه فيضيع وقته دون أي إنجاز ملموس، وقد يكثر عليه العقوبات لكثرة غياباته وأخطائه لعدم ارتياحه بالمكان الذي هو فيه...!", "بوصلة الحياة تتحدّد من الصغر، نعم من الضروري الدراسة للاختبارات والحصول على درجات عالية للدخول للتخصصات المرموقة، ولكن التخصص المرموق هو ذلك التخصص الذي يجد الموظف فيه نفسه، وليس المنصب الذي يريد أن يراه الناس فيه.", "البعض يحب خدمة الناس ويرغب في الإنجاز فيذهب للوظائف الاجتماعية، والبعض لا يحب الاحتكاك بالآخرين فيذهب للأماكن التي تكون بعيداً عن الاحتكاك بالجمهور، ولا يسعى الشاب لتطوير مهاراته وإمكاناته والإنجاز الأكبر.", "اختيار التخصص يتطلب من الشخص معرفة 3 أمور مهمة: تبدأ بالقدرة والإمكانات التي يتمتع بها الفرد، ولا يستطيع الفرد معرفة قدراته ما لم يجرب ويخرج من الدائرة المغلقة، والأمر الآخر الذي يجب أن يلتفت إليه الشاب معرفة رغبته والصورة النمطية التي يحب أن يعمل بها، فبعض الناس يجيدون عمل الحسابات والميزانيات، ولكن لا يحبون العمل بها، والبعض يجيد الشرح والحديث أمام الجمهور، ولكن لا يرغب التدريس والشرح.", "والجانب الأخير الذي يعتبر ذا أهمية أيضاً الفرصة الموجودة في هذا التخصص، وحاجة سوق العمل، وإمكانية الإبداع والتميز في أداء هذه المهنة.", "وصيتي إلى الشباب البحث عن التخصّص الذي يجدون فيه أنفسهم، والجلوس مع أهل الخبرات والمجربين، ولا يتحسرون على سنوات الدراسة وتغيير التخصص، نعم العمر يمضي، ولكن الحياة يجب أن تمضي، والإنسان يكون سعيداً وفخوراً بإنجازه وعمله."]}, "cut": "art/ar26-9-a.jpg", "author": "عبدالله الفرحان", "face": "art/ar26-9-p.jpg"}, {"id": "ar26-10", "lang": "ar", "fresh": true, "custom": true, "img": "art/ar26-10.jpg", "pages": [1], "title": {"ar": "شركة \" فوتو توب\" توسع نطاق عملها ليشمل تطبيقات تحويل المركبات من حماية الدوائر الكهربائية إلى حلول المركبات المجهزة للتخييم"}, "sum": {"ar": "على مدار أكثر من 30 عاماً، تخصصت شركة \" فوتو توب\" في منتجات الحماية الكهربائية للسيارات، بما في ذلك الصمامات (الفيوزات)، وحوامل الصمامات، وقواطع الدائرة، وصناديق…"}, "body": {"ar": ["على مدار أكثر من 30 عاماً، تخصصت شركة \" فوتو توب\" في منتجات الحماية الكهربائية للسيارات، بما في ذلك الصمامات (الفيوزات)، وحوامل الصمامات، وقواطع الدائرة، وصناديق الصمامات، والملحقات ذات الصلة. واليوم، تنتقل من مجرد تصنيع المكونات إلى تقديم حلول عملية لتطبيقات المركبات.", "تشهد تايوان تزايداً ملحوظاً في شعبية التخييم والسفر بالمركبات المتنقلة؛ حيث أصبحت المركبات مثل: \"كامبر فانس\" و\"تويوتا\" تُستخدم على نطاق واسع كأساس لتحويلها إلى مركبات مجهزة للتخييم.", "شركة \" فوتو توب\" توظف خبرتها في الأنظمة الكهربائية للسيارات لدعم مشاريع التحويل هذه؛ إذ  تشمل: الصمامات المسطحة وحوامل الصمامات المقاومة للماء، وقواطع الدائرة، وصناديق الصمامات، ومكونات حماية البطارية- في المركبة لتشغيل أنظمة الإضاءة، ومنافذ شحن، والبطاريات الإضافية، وغيرها من المعدات الكهربائية.", "ومن خلال المشاركة المباشرة في مشاريع تحويل المركبات، تكتسب فهماً أعمق لكيفية تركيب منتجاتها واستخدامها في ظروف واقعية.", "وهذا يتيح لها تطوير منتجات لا تقتصر على منظور التصنيع فحسب، بل تلبي أيضاً متطلبات التركيب الفعلية واحتياجات المستخدمين.", "وانطلاقاً من مكونات حماية الدوائر الكهربائية ووصولاً إلى تطبيقات المركبات المتكاملة، تواصل شركة \" فوتو توب\" استكشاف فرص جديدة في قطاعات المركبات المجهزة للتخييم، والمركبات الترفيهية، والمركبات التجارية، وغيرها من أسواق السيارات.", "معلومات التواصل:", "PHOTO-TOP TECHNOLOGIES CO., LTD.", "## www.photo-top.com.tw", "## Email：sales1@photo-top.com.tw", "Address: No. 57, Lane 458, Section 4, Zhonghua Rd, Xiangshan District, Hsinchu City, Taiwan 30060."]}, "fit": 1}, {"id": "ar26-11", "lang": "ar", "fresh": true, "custom": true, "img": "art/ar26-11.jpg", "pages": [1], "title": {"ar": "ماليزيا تضع مفهوم “المنتجات الصحية الحلال” و”الوجبات الفاخرة السريعة” في قلب فعاليات جلفود 2026"}, "sum": {"ar": "تشارك هيئة تطوير التجارة الخارجية الماليزية \"ماتريد\" بوفد يضم أكثر من 120 عارضاً ماليزياً في معرض جلفود 2026، أكبر معرض سنوي للأغذية والمشروبات في العالم، في مركز دبي…"}, "body": {"ar": ["تشارك هيئة تطوير التجارة الخارجية الماليزية \"ماتريد\" بوفد يضم أكثر من 120 عارضاً ماليزياً في معرض جلفود 2026، أكبر معرض سنوي للأغذية والمشروبات في العالم، في مركز دبي التجاري العالمي ومركز دبي للمعارض حيث تجسد حقبة جديدة من التميز في قطاع الأغذية والمشروبات، مرتكزة على ركيزتين أساسيتين: الابتكار الصحي والراحة الفاخرة.", "وفي الوقت نفسه، افتتح سعادة \"داتو تنغكو سراج الزمان بن تنغكو محمد عارفين\" سفير ماليزيا لدى دولة الإمارات العربية المتحدة جناح بلاده المشاركة في معرض “جلفود 2026″ بمدينة أكسبو دبي، مؤكّدا أولوية ماليزيا في تعزيز الروابط التجارية مع الإمارات والمنطقة وقال خلال تدشين الجناح الماليزي: “الإمارات تعد بوابة رئيسية للمنتجات الماليزية للوصول إلى سوق الشرق الأوسط وشمال إفريقيا الذي يضم 400 مليون نسمة، ووجود عدد كبير من الشركات الماليزية هنا يظهر ثقتنا بالإمارات، ودبي. وهذا أيضاً دليل على أننا نستطيع أن نجد شريكاً جيداً في المنطقة”.", "وأضاف خلال لقاء صحافي: “بالطبع، هناك ميزة “الحلال” في ماليزيا؛ التي تعتبر رائدة عالمياً في", "صناعة الحلال، حيث معايير الحلال التي تضعها هيئة تمنح المستهلكين والمشترين في دول مجلس", "التعاون الخليجي الطمأنينة فيما يخص الجودة والسلامة والالتزام الديني”.", "وقال: “إذا شاهدتم المنتجات، ستلاحظون تنوّعها؛ فنحن لا نعرض فقط السلع الأساسية، بل نقدم ابتكارات عالية القيمة، بما في ذلك القهوة المتخصصة والزيوت الصالحة للأكل عالية الجودة والمناسبة للصحة، وعلى سبيل المثال، منتج (ام ام دي) الذي تمّ إطلاقه مؤخراً، سهل الاستخدام فقط بالماء والميكروويف، وكان لذيذاً جداً”.", "وأوضح: “كما أن الدعم الحكومي واضح من خلال حضور وكالات متعددة، ووزارة الزراعة، ووزارة الأمن الغذائي، وقطاع المشاريع الصغيرة والمتوسطة، وهذا يبرز النهج الموحد لماليزيا في الترويج لمنتجاتها. وسنواصل تصدير جميع الأغذية المصنعة إلى الإمارات ونموّ هذا القطاع.", "وتعتبر فعاليات “جلفود” ضرورية لتمكين الشركات الصغيرة والمتوسطة من الانتقال من النجاح المحلي إلى أن تصبح علامات تجارية عالمية. لقد تحدثت مع بعض الشركات والتعاونيات التي بدأت تسوق منتجاتها خارج البلاد، فهي مرتاحة محلياً والآن تستكشف الأسواق الخارجية.", "كما أن التركيز على الاستدامة مهم؛ فالشركات الماليزية، وخاصة في قطاع الوجبات السريعة، تعرض ممارسات مستدامة وحلول زيت النخيل الخالي من إزالة الغابات لمواكبة اللوائح العالمية المتطورة. وهذه بعض المجالات الأساسية التي نركز عليها حالياً”.", "## الثقافة والطعام الماليزي", "وردّاً على سؤال حول الثقافة والطعام والشعب والأمة كلها، قال سعادة السفير: “يجب زيارة ماليزيا لتجربة الطعام الماليزي، فهذا العام هو عام زيارة ماليزيا 2026، ونشجع الناس على الذهاب إلى ماليزيا لتذوق الطعام الماليزي، ثم شراء المنتجات الماليزية المتوفرة في الخارج لتذكيرهم بماليزيا. فشراء الطعام وحده لا يربطه بالثقافة، لكن زيارة ماليزيا تتيح تجربة شاملة تربط الطعام بالنكهة والثقافة والشعب، نعم، طعم ماليزيا الحقيقي”.", "## ماليزيا تستثمر في الحلال", "ومع توقّع وصول السوق العالمي للحلال إلى 5 تريليونات دولار أمريكي بحلول عام 2030، تستثمر ماليزيا موقعها كقائد عالمي في منتجات الحلال لتقديم منتجات تلبي احتياجات المستهلك العصري في الدول العربية، وتبرز مشاركة هذا العام تحولاً استراتيجياً من تصدير المواد الخام إلى تقديم حلول غذائية مصنعة عالية القيمة.", "ويبرز ضمن وفد “ماتريد” لعام 2026 اتجاه متصاعد نحو مفهوم “الوجبات الفاخرة السريعة”، حيث تتخصص أكثر من 70 شركة في الصلصات والمعاجين الفاخرة، ويعمل نحو 50 منها على الوجبات الجاهزة للأكل. وتضع ماليزيا نفسها كخيار رئيسي للفئة المهنية المشغولة في دول الخليج، من خلال منتجات تستخدم تقنيات حديثة في التعقيم والتجميد لتقديم تجارب طهي أصيلة وبسيطة، تنقل النكهات المعقدة لآسيا إلى المنازل الشرق أوسطية في دقائق معدودة.", "## 40 عارضاً لمنتجات عضوية", "واستجابةً لأجندات الصحة الوطنية في دول الخليج، يضم جناح ماليزيا قسماً مهماً بعنوان “أفضل لصحتك”، حيث يعرض أكثر من 40 عارضاً منتجات عضوية وخالية من الكائنات المعدلة وراثياً، وخالية من الغلوتين، ونباتية. ومن المشروبات الوظيفية والمشروبات العشبية الصحية إلى الوجبات الخفيفة منخفضة المؤشر الجلايسيمي، تعيد ماليزيا تعريف مفهوم الحلال ليشمل ليس فقط الامتثال الاسلامي، بما في ذلك الصحة الشاملة وسلامة الغذاء.", "وفي عام 2025، واصل قطاع الأغذية المصنعة الماليزية مساره التصاعدي نحو المنطقة العربية وشمال إفريقيا، مسجلاً رقماً قياسياً بلغ 2.52 مليار رينغيت ماليزي، بزيادة 4.2٪ عن العام السابق. وكانت صادرات العام نفسه 2.42 مليار رينغيت، فيما بلغت الواردات 1.0 مليار رينغيت."]}}, {"id": "ar26-12", "lang": "ar", "fresh": true, "custom": true, "img": "art/ar26-12.jpg", "pages": [1], "title": {"ar": "مسلمون يهدمون أجزاء من مسجد تاريخي بالهند وهم يبكون... ما القصة؟"}, "sum": {"ar": "في مشهد لافت بمدينة \"أوجين\" الهندية، أقدم مسلمون على إزالة جزء من مسجد \"شاهي\" التاريخي بأيديهم وهم يذرفون الدموع، في محاولة لتفادي هدمه بالجرافات عقب تسوية قضائية صادرة…"}, "body": {"ar": ["في مشهد لافت بمدينة \"أوجين\" الهندية، أقدم مسلمون على إزالة جزء من مسجد \"شاهي\" التاريخي بأيديهم وهم يذرفون الدموع، في محاولة لتفادي هدمه بالجرافات عقب تسوية قضائية صادرة عن المحكمة العليا بولاية ماديا براديش.", "وكانت المحكمة العليا قد أيّدت قرار السلطات المحلية بإزالة قاعة المسجد ومئذنته، رافضة الالتماسات التي تقدمت بها إدارة المسجد -المسجل رسميا كوقف إسلامي- للطعن في قرار البلدية.", "وبينما اندلعت احتجاجات رفضا لقرار السلطات بالهدم، قامت الشرطة بقمع المحتجّين، واستخدمت الغاز المسيل للدموع لتفريقهم...", "## دموع أثناء الهدم", "ووثّقت مقاطع فيديو تداولتها حسابات هندية مشاهد مؤثرة لمسلمين يبكون أثناء هدمهم أجزاء من \"مسجد شاهي\" الذي يعود تاريخه إلى نحو 600 عام.", "وأظهرت المشاهد عمليات هدم يدوية لجزء بارز ممتد على مساحة 3 أقدام من المسجد، نفذها أعضاء من لجنة المسجد، في محاولة لمنع السلطات الرسمية من الاستعانة بالجرافات لتنفيذ الهدم.", "وبحسب صحيفة \"إنديان إكسبرس\" الهندية، فقد وصلت فرق الشرطة والبلدية مزوّدة بجرّافات وآليات ثقيلة أخرى، إلا أن المحتجّين المحتشدين خارج المسجد حالوا دون بدء عملية الهدم، بينما قضى محتجّون الليلة داخل المسجد، مشدّدين على عدم السماح بإزالة أي جزء منه...", "وأظهرت لقطات متداولة عبر منصات التواصل الاجتماعي احتشاد المئات في ساحة المسجد وحرمه، حيث افترشوا الأرض طوال الليل ورفضوا إخلاء المكان...", "لماذا الهدم؟", "تأتي خطوة الهدم الجزئي ضمن مشروع لبلدية أوجين لتوسيع طريق محلي ليصل عرضه إلى 15 متراً، استعداداً لمهرجان \"سيمهاستا كومب مارسته\" من المقرر إقامته في عام 2028 وهو طقس حج هندوسي.", "ووفق \"إنديان إكسبرس\"، طالبت لجنة المسجد وأفراد من الجالية المسلمة بتوسيع الطريق عبر مسار بديل أو بإزالة المباني المقابلة للمسجد، كما طعنوا مرتين في قرار الهدم أمام المحكمة، بحكم أن المسجد مسجل كوقف إسلامي، لكن محكمة ماديا براديش العليا أصدرت قرارا برفض الطعون المقدّمة.", "وكانت لجنة إدارة المسجد قد توصّلت إلى تسوية مع إدارة الولاية تقضي بإزالة البروز، وهو جزء لا تُقام فيه الصلاة، وذلك بدلا من اقتطاع 9.5 أقدام كما كانت تطالب الإدارة سابقا.", "وفي هذا السياق، أكّد إمام المسجد محمد إبراهيم ضرورة استثناء دور العبادة من مشاريع التوسعة، قائلا: \"هذه مدينة دينية، ولا يجوز هدم أي من المواقع الدينية. يجب أن تتم التوسعة دون المساس بهذه المواقع\".", "## احتجاجات ومواجهات مع الشرطة", "وجاءت عمليات التفكيك اليدوي بعد مواجهات بين محتجين مسلمين والشرطة الهندية، التي عزّزت وجودها في المنطقة بعد أن أقامت السلطات حواجز ونشرت جرافات حول المسجد، تمهيدا لبدء عمليات الهدم، خلافا للاتفاق الذي ينصّ على أن تقوم لجنة المسجد بعمليات الهدم ذاتيا.", "ووثّقت مقاطع فيديو وقوع صدامات بين قوات الشرطة والمحتجين المعتصمين الذين شكّلوا درعاً بشرية لحماية المبنى...", "ونشرت حسابات هندية مشهداً لافتاً لوقوف شاب بثبات في وجه عناصر الشرطة، الذين ألقوا قنابل الغاز المسيل للدموع لتفريق الاحتجاجات التي نظمتها الجالية المسلمة بالولاية.", "وأظهر المشهد انتشارا كثيفا لعناصر الشرطة خلف حواجز أمنيّة جرى نصبها في محيط مسجد \"شاهي\"، بينما وقف الشاب بثبات لافت أمامهم وسط الدخان الكثيف الصادر عن قنابل الغاز...", "ولا تُعد هذه الأزمة الأولى من نوعها في سياق التحضيرات للمهرجان الهندوسي؛ ففي عام 2025، شهدت مدينة أوجين عمليات هدم شملت مساجد ومنازل في حي \"نظام الدين\" ذي الأغلبية المسلمة، وذلك لتوسعة ممر معبد \"ماها كاليشور\" استعدادا لمهرجان 2028."]}}, {"id": "ar26-13", "lang": "ar", "fresh": true, "custom": true, "img": "art/ar26-13.jpg", "pages": [1], "title": {"ar": "معرض ماليزيا الدولي للمنتجات الحلال 2026 يستهدف 1.23 مليار دولار من التجارة"}, "sum": {"ar": "يعود معرض ماليزيا الدولي للمنتجات الحلال (ميهاس 2026) خلال الفترة من 23 إلى 26 سبتمبر، مستهدفاً تحقيق صفقات تجارية بقيمة طموحة تبلغ 5 مليارات رينغيت ماليزي، في مؤشر يعكس…"}, "body": {"ar": ["يعود معرض ماليزيا الدولي للمنتجات الحلال (ميهاس 2026) خلال الفترة من 23 إلى 26 سبتمبر، مستهدفاً تحقيق صفقات تجارية بقيمة طموحة تبلغ 5 مليارات رينغيت ماليزي، في مؤشر يعكس الزخم المتسارع الذي يشهده الاقتصاد الحلال العالمي، والذي يواصل نموّه دون مؤشرات على التباطؤ. وتؤكد دورة هذا العام مكانة ماليزيا المتقدمة في سوق تزداد فيه المنافسة، إذ تجمع الفعالية 2,380 جناحاً للعرض، ونحو 45 ألف زائر من المتخصصين في التجارة من 45 دولة، إلى جانب قائمة منتقاة تضم 600 مُصدّر ماليزي، تم إعدادهم للاستفادة من فرص إبرام صفقات تجارية قد تحقق مستويات قياسية.", "## وضع المعايير للتجارة الحلال العالمية", "لم يعد معرض ماليزيا الدولي للمنتجات الحلال (ميهاس 2026) مجرد معرض تجاري، بل أصبح مؤشراً رئيسياً لقياس مستوى الحيوية والطموح في الاقتصاد الحلال العالمي. ومن خلال برنامج التوريد الدولي، ستُتاح مفاوضات تجارية رفيعة المستوى بين 200 مشترٍ دولي مؤهل ومصنّعين ماليزيين، بينما يستقطب برنامج المشترين المستضافين نحو 50 من صناع القرار ممن يمتلكون صلاحيات مباشرة لاتخاذ قرارات الشراء والتوريد.", "ويعكس هذا النهج المنظم في توليد الصفقات تحولاً أوسع في قطاع التجارة الحلال؛ إذ ينتقل التركيز تدريجياً من النمو القائم على زيادة حجم التعاملات إلى تجارة تركز على النتائج الفعلية، وتستند إلى الثقة والشفافية وإمكانية قياس النتائج.", "## الصورة الاقتصادية الأوسع", "تقدم التجربة الماليزية نموذجاً لافتاً في هذا المجال. فقد وضعت البلاد هدفاً للوصول بحجم سوق المنتجات الحلال إلى 523.5 مليار رينغيت ماليزي بحلول عام 2030، بما يُقدّر أن يسهم بنحو 11% من الناتج المحلي الإجمالي، ويوفر أكثر من 700 ألف فرصة عمل.", "ولا تبدو هذه الأهداف مجرد طموحات، بل تستند إلى بنية تحتية ومؤسسات متطورة. فقد احتلت ماليزيا المرتبة الأولى في مؤشر الاقتصاد الإسلامي العالمي لعامي 2025–2026، متقدمة في قطاعات الغذاء الحلال، والتمويل الإسلامي، والأدوية ومستحضرات التجميل، وهي من القطاعات الرئيسية التي تقود إنفاق المستهلكين المسلمين عالمياً، والذي يصل إلى مستويات تقدر بتريليونات الدولارات.", "## تنوع القطاعات: 14 قطاعاً في منصة واحدة", "يغطي (معرض ماليزيا الدولي للمنتجات الحلال 2026) أربعة عشر قطاعاً استراتيجياً، تشمل الأغذية والمشروبات، والأدوية، والتمويل الإسلامي، والأزياء المحتشمة، ومنتجات العناية الشخصية، ومستحضرات التجميل، والتكنولوجيا، والخدمات اللوجستية الحلال، والسياحة الصديقة للمسلمين، إلى جانب العديد من القطاعات الأخرى.", "وبالنسبة إلى المُصدّرين من جنوب آسيا وأفريقيا على وجه الخصوص، يمثل معرض ماليزيا الدولي للمنتجات الحلال 2026 بوابة مهمّة ليس فقط إلى السوق الماليزية، وإنما أيضاً إلى تعميق الاندماج داخل رابطة دول جنوب شرق آسيا (آسيان). وتزداد أهمية هذه البوابة في ظل التحولات المتسارعة في بيئة الرسوم الجمركية وأولويات سلاسل الإمداد العالمية، بما يجعل الوصول إلى أسواق جديدة وتنويع الشركاء التجاريين عنصراً متزايد الأهمية في الاستراتيجيات التجارية الدولية."]}, "fit": 1}];
  W.AAT_ARTICLES = X.concat(W.AAT_ARTICLES || []);
})(window);

/* English news: shown in every language except Arabic */
(function (W) { var X = [{"img": "enn1", "title": "From Circuit Protection to Camper Van Solutions: Photo-Top Expands into Vehicle Conversion Applications", "body": ["For more than 30 years, Photo-Top Technologies has specialized in automotive electrical protection products, including fuses, fuse holders, circuit breakers, fuse boxes, and related accessories.", "Today, we are expanding from component manufacturing into practical vehicle applications.", "In Taiwan, camping and mobile travel are becoming increasingly popular. Vehicles such as the Toyota Town Ace and JSPACE are now widely used as platforms for camper van conversions.", "Photo-Top is applying its experience in automotive electrical systems to these conversion projects. Our products, including blade fuses, waterproof fuse holders, circuit breakers, fuse boxes, and battery protection components, can be integrated into the vehicle to support lighting, USB charging, auxiliary batteries, and other electrical equipment.", "By participating directly in vehicle conversion projects, we can better understand how our products are installed and used in real applications.", "This allows us to develop products not only from a manufacturer’s perspective, but also based on actual installation and user needs.", "From circuit protection components to complete vehicle applications, Photo-Top continues to explore new opportunities in camper vans, recreational vehicles, commercial vehicles, and other automotive markets.", "Contacts:", "PHOTO-TOP TECHNOLOGIES CO., LTD.", "www.photo-top.com.tw", "Email：sales1@photo-top.com.tw", "Address: No. 57, Lane 458, Section 4, Zhonghua Rd, Xiangshan District, Hsinchu City, Taiwan 30060."]}, {"img": "enn2", "title": "Premier Highlights Taiwan’s Key Role in Global AI Development", "body": ["Taiwan is playing a key role in the global AI revolution and is expected to remain central to semiconductor industry growth, Premier Cho Jung-tai said at the opening of SEMICON Taiwan 2026.", "Taiwan’s semiconductor production value reached US$209.1 billion in 2025, up 22.7% year over year, while TSMC and other major global companies continue investing in advanced manufacturing, packaging, and memory production.", "SEMI President and CEO Ajit Manocha stated that Taiwan is a major global AI hub and a trusted industry partner, forecasting that global semiconductor revenue could reach US$2 trillion by 2030, driven by AI. As AI shifts from training toward inference, demand is expected to increase for memory, higher bandwidth, advanced packaging, and silicon photonics.", "Cho said the government will provide the land, energy, talent, and financial support needed for industry expansion, including factory space that allows companies to accelerate production.", "SEMICON Taiwan 2026 features more than 1,300 exhibitors and 4,300 booths from over 60 countries and regions."]}, {"img": "enn3", "title": "New Models, Hybrids and EVs to Drive Taiwan’s Auto Market", "body": ["Taiwan’s automotive market is expected to gain momentum in the second half of the year as automakers introduce new models, expand hybrid offerings and develop the electric vehicle market. Replacement demand remains a key source of sales, while consumers increasingly focus on product value and innovation.", "Recent launches from Mercedes-Benz, BMW, Peugeot, Mazda and Volkswagen are intensifying competition across vehicle segments. BMW’s new iX3 electric SUV is expected to begin deliveries in the fourth quarter, with its 2026 allocation already sold out. Mercedes-Benz is also introducing new CLA and GLB models, including both combustion-engine and fully electric versions.", "Automakers are also using facelifts, special editions and equipment upgrades to strengthen their lineups. MG, under China Motor Corp, has launched the 2027 ZS, which can be purchased for less than US$18,750 with Taiwan’s vehicle trade-in incentive.", "Compared with last year, improved vehicle availability and a broader range of new products are expected to support sales in the second half."]}, {"img": "enn4", "title": "Taiwan Showcases Sustainability Innovation at 2026 SDG Asia Expo", "body": ["The fifth SDG Asia Expo, held in Taipei under the theme “Shape Our Future: Resilience, Innovation, Prosperity,” showcased Taiwan’s sustainability efforts across government, business, healthcare, education, and daily life.", "The expo featured nine zones covering sustainable architecture, finance, living, tourism, education, healthcare, solutions, partnerships, and ecosystems. Key themes included AI, energy transition, smart healthcare, circular economy, and biodiversity.", "Taiwan Institute for Sustainable Energy Chairman Eugene Chien said sustainability is entering an “ESG 2.0” era, with energy, security, and geopolitics joining environmental, social, and governance priorities. President Lai Ching-te emphasized national resilience amid climate change, geopolitical tensions, and supply -chain restructuring.", "Government and corporate exhibits highlighted renewable energy, smart grids, carbon management, low-carbon healthcare, circular products, and sustainable agriculture. Examples included reusable healthcare containers, recycled coffee grounds, recycled plastics, water-saving crops, and recyclable architectural models.", "The expo also emphasized biodiversity and community services, demonstrating how sustainability is increasingly integrated into Taiwan’s industries, public services, and everyday consumer choices."]}, {"img": "enn5", "title": "Taiwan Excellence Debuts at LEAP 2026 in Saudi Arabia", "body": ["Taiwan Excellence made its debut at Saudi Arabia’s LEAP 2026 technology exhibition, held in Riyadh from August 31 to September 3, highlighting opportunities for Taiwan-Saudi technology cooperation. Saudi Arabia has designated 2026 as the “Year of AI” and aims to expand data-center capacity to 1.5 GW by 2030 and 6.6 GW within a decade.", "Taiwan officials said the rapid development of AI, digital infrastructure, and smart cities under Vision 2030 is creating opportunities for Taiwanese technology companies. The Taiwan Excellence presentation featured ASUS, Pegatron, Advantech, and AAEON, showcasing technologies supporting digital transformation in the Middle East.", "The exhibition area focused on three themes: AI computing and networking infrastructure, industrial edge and smart applications, and smart mobility and digital lifestyle. Taiwan External Trade Development Council Chairman James C. F.", "Huang said Taiwan’s strengths span computing, hardware manufacturing, system integration, and end-user applications, allowing it to complement Saudi Arabia’s technology development. The initiative aims to expand business connections and strengthen long-term economic and technology cooperation between Taiwan and Saudi Arabia."]}, {"img": "enn6", "title": "Taiwan’s Smart Mobility Ecosystem Powers More Than Vehicles", "body": ["Taiwan is emerging as a technology partner in the global shift toward smarter, cleaner, and more connected mobility, combining strengths in semiconductors, ICT, and precision manufacturing to support software-defined vehicles (SDVs).", "Its integrated automotive ecosystem spans automotive semiconductors, smart cockpits, advanced driver assistance systems (ADAS), EV battery technologies, charging systems, and vehicle connectivity. The combination of flexible manufacturing, engineering expertise, and rapid customization also supports faster R&D and shorter time-to-market.", "Taiwan’s automotive electronics sector is expected to exceed US$18.6 billion by the end of 2026, already surpassing traditional auto parts production as AI, electrification, and connectivity reshape the industry.", "High-performance computing, automotive system-on-chip solutions, AI cockpit platforms, and power electronics provide the computing capabilities required by SDVs, while 5G and vehicle-to-everything (V2X) technologies enable real-time connectivity and data exchange.", "Industry executives say Taiwan’s key advantage is increasingly shifting from individual components toward intelligent system integration. The same technologies can also support smart-city applications, linking mobility, communications, energy management, and urban infrastructure.", "For automakers in North America, Japan, and Europe, Taiwan’s ecosystem offers opportunities to work with suppliers not only on individual components but also on integrated vehicle systems and next-generation mobility technologies."]}, {"img": "enn7", "title": "Taiwan’s Tongtai Expands Machine Tool Capabilities into Semiconductor Equipment", "body": ["Tongtai Machine & Tool is expanding its semiconductor business by combining its electronics equipment and precision machine tool capabilities, targeting wafer processing, advanced packaging, and semiconductor equipment manufacturing.", "The company’s electronics unit provides grinding and flattening equipment for wafer manufacturing, packaging, and recycling. It has also developed ductile grinding for hard materials such as silicon carbide, enabling nanometer-scale material removal while reducing surface damage and processing steps.", "Tongtai’s machine tool business produces precision components for semiconductor equipment using high-precision turning, milling and ultrasonic processing. Products include gas-control systems, wafer carriers and process chambers.", "The company also supplies laser-processing equipment for advanced packaging, with systems capable of creating micro-holes and openings in multilayer structures while limiting heat-affected areas and surrounding material damage.", "Tongtai primarily manufactures machine tools and industrial processing equipment. Revenue reached US$20.9 million in July, up 57.1% year over year, according to Sinotrade.", "The expansion reflects growing opportunities for Taiwan’s machine tool expertise in semiconductor manufacturing and advanced packaging."]}];
  var D = W.AAT_DATA, NB = W.AAT_NEWS_BODY = W.AAT_NEWS_BODY || []; if (!D || !D.news) return;
  X.forEach(function (x) { var i = D.news.length; D.news.push({ img: x.img, title: { en: x.title }, only: "en" }); NB[i] = { body: { en: x.body } }; });
})(window);

